rules.selector:
/* v0.12: 3D viewer frame. Same glass treatment as op-room-frame so the
     two left-column windows read as a matched pair. */
  .op-room-3d-frame

/* ───────── v0.25: page indicator, smaller (~20% slimmer) + pushed
     further left so it doesn't kiss the window edges. */
  #page-indicator

/* the drawer is a floating glass panel inside its pane (top 60 · right 18 · bottom 22) */
  /* v13.44: full height, like every drawer in MAYA now. */
  .drawer

/* v7.2: all top-bar pills, liquid glass. Same gradient + backdrop blur
     + specular shadow on every variant. */
  .top-btn

/* notes-dot was originally scoped to #notes-toggle, also apply to hamburger
     so a draft consultation still glows when there's something worth saving. */
  #hamburger-toggle .notes-dot

/* v5.1: Dissect button, only on UPLOADED inspo cards (not Maya visions).
     v10.2: canon pill chrome. */
  .item-card .dissect-btn

/* v13.1: the tip amounts. These were using a class that does not exist here,
     so they rendered as plain white browser buttons sitting on the glass. */
  .tip-amt

/* v8.3: wrap auto-sizes to the image, no dark margins around the
     visualized image. Liquid glass shell wraps the actual content edge. */
  #garment-image-wrap

/* v11.18: collapsible "Attributes", ref tags hide behind a toggle pill.
     Collapsed by default; opens when #garment-modal gets .attrs-open. */
  .attributes-toggle

/* v10.9: construction dissection panel, hidden under the card, slides
     up on hover. Shows garment type, panels, complexity, fabric source. */
  .favorite-card .fc-dissection

/* v13.58: the terms popup. First sign in only; Agree wakes at the end of
     the text. Same glass as everything else. */
  #tos-modal

/* lighter glass on phones, blur is the priciest effect on mobile GPUs;
       this is the single biggest smoothness win per frame. */
    .item-card

